/* HEXA BATTLEGROUNDS setup — PART 58 OF 79. Run parts in order. Safe to re-run. */ create or replace function _plane_xy(a arenas) returns float8[] language plpgsql stable as $$ declare p float8; begin if a.plane_t0 is null then return null; end if; p := least(1, greatest(0, extract(epoch from now() - a.plane_t0) / greatest(1, extract(epoch from a.plane_t1 - a.plane_t0)))); return array[a.plane_ax + (a.plane_bx - a.plane_ax) * p, a.plane_ay + (a.plane_by - a.plane_ay) * p, p]; end $$; create or replace function _plane_launch(p_arena uuid) returns void language plpgsql as $$ declare a arenas; ang float8 := random() * 2 * pi(); cx float8 := 0.5 + (random() - 0.5) * 0.24; cy float8 := 0.5 + (random() - 0.5) * 0.24; dx float8; dy float8; v_secs int; begin select * into a from arenas where id = p_arena; dx := cos(ang); dy := sin(ang); v_secs := _cfg(a.event_id, 'plane_seconds'); update arenas set plane_ax = cx - dx * 0.95, plane_ay = cy - dy * 0.95, plane_bx = cx + dx * 0.95, plane_by = cy + dy * 0.95, plane_t0 = now(), plane_t1 = now() + _secs(v_secs) where id = p_arena returning * into a; update arenas set overlay = overlay || jsonb_build_object('plane', jsonb_build_object( 'a', jsonb_build_array(a.plane_ax, a.plane_ay), 'b', jsonb_build_array(a.plane_bx, a.plane_by), 't0', a.plane_t0, 't1', a.plane_t1)) where id = p_arena; perform _feed(p_arena, 'plane.over', '{}'::jsonb); end $$; create or replace function _do_jump(p_team uuid, p_loc text, p_from float8[]) returns numeric language plpgsql as $$ declare t teams; l locations; d float8; v_secs numeric; g float8; begin select * into t from teams where id = p_team for update; select * into l from locations where id = p_loc; d := sqrt((l.x - p_from[1]) ^ 2 + (l.y - p_from[2]) ^ 2); g := greatest(0.05, _cfg(t.event_id, 'glide_range') / 1000.0); v_secs := round((_cfg(t.event_id, 'drop_seconds') * (0.6 + 0.6 * least(1, d / g)))::numeric, 1); update teams set state = 'traveling', travel_from = location_id, travel_to = l.id, travel_started_at = now(), travel_arrive_at = now() + _secs(v_secs), travel_fx = p_from[1], travel_fy = p_from[2], pos_x = p_from[1], pos_y = p_from[2], pos_at = now(), vehicle = 'none', buggy_x = null, buggy_y = null where id = p_team; perform _feed(t.arena_id, 'squad.jumped', jsonb_build_object('team', t.number, 'to', l.id)); perform _ping_team(p_team, 'move'); perform _ping_arena(t.arena_id, 'move'); return v_secs; end $$; do $$ declare d text; n text; begin d := pg_get_functiondef('captain_move(text, text)'::regprocedure); n := regexp_replace(d, 'cur := _team_xy\(t\);(\s*)d := sqrt\(\(l\.x - cur\[1\]\) \^ 2 \+ \(l\.y - cur\[2\]\) \^ 2\);', ' if not t.dropped and _cfg(t.event_id, ''br_mode'') = 1 then
    if t.state = ''traveling'' then raise exception ''BUSY''; end if;
    cur := _plane_xy(a);
    if cur is null or cur[3] >= 0.99 then raise exception ''PLANE_GONE''; end if;
    if cur[1] < 0.0 or cur[1] > 1.0 or cur[2] < 0.0 or cur[2] > 1.0 then raise exception ''NOT_OVER_CAMPUS''; end if;
    if sqrt((l.x - cur[1]) ^ 2 + (l.y - cur[2]) ^ 2) > _cfg(t.event_id, ''glide_range'') / 1000.0 then raise exception ''TOO_FAR_TO_GLIDE''; end if;
    v_secs := _do_jump(t.id, l.id, cur);
    return jsonb_build_object(''arrive_at'', now() + _secs(v_secs), ''seconds'', v_secs, ''jump'', true);
  end if;
  cur := _team_xy(t);
  d := sqrt((l.x - cur[1]) ^ 2 + (l.y - cur[2]) ^ 2);'); n := replace(n, 'v_secs := greatest(1, round((d / (_cfg(t.event_id, ''move_speed'') / 1000.0))::numeric, 1));', 'v_secs := greatest(1, round((d / _team_speed(t))::numeric, 1));'); if n = d or position('_do_jump' in n) = 0 then raise exception 'v6: could not patch captain_move'; end if; execute n; end $$; create or replace function _auto_roles(p_arena uuid) returns boolean language plpgsql as $$ declare t record; p record; v_missing text[]; v_any boolean := false; begin if _cfg((select event_id from arenas where id = p_arena), 'br_mode') = 0 then return false; end if; for t in select * from teams where arena_id = p_arena and ready loop select array_agg(r order by array_position(array['captain', 'scout', 'decoder', 'intel'], r)) into v_missing from unnest(array['captain', 'scout', 'decoder', 'intel']) r where not exists (select 1 from players where team_id = t.id and active and role = r); if v_missing is null then continue; end if; for p in select * from players where team_id = t.id and active and role is null order by random() loop exit when array_length(v_missing, 1) is null; update players set role = v_missing[1] where id = p.id; v_missing := v_missing[2:]; v_any := true; end loop; if v_any then perform _ping_team(t.id, 'roles'); end if; end loop; return v_any; end $$; create or replace function join_flight(p_event_code text, p_map int, p_pin text, p_name text, p_consent boolean, p_rules boolean, p_existing_token text default null) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; v_num int; v_n int; v_any int; begin select id into v_ev from events where code = upper(trim(coalesce(p_event_code, ''))); if v_ev is null then return join_team(p_event_code, 1, p_pin, p_name, p_consent, p_rules, p_existing_token); end if; if (select count(*) from pin_failures where event_id = v_ev and team_number = -p_map and at > now() - interval '5 minutes') >= 30 then raise exception 'LOCKED_OUT'; end if; select count(*), min(t.number) into v_n, v_num from teams t join arenas a on a.id = t.arena_id where t.event_id = v_ev and a.number = p_map and t.pin_hash = _hash(t.pin_salt || coalesce(p_pin, '')); if v_n > 1 then return jsonb_build_object('error', 'PIN_AMBIGUOUS'); end if; if v_n = 0 then select min(t.number) into v_any from teams t join arenas a on a.id = t.arena_id where t.event_id = v_ev and a.number = p_map; if v_any is null then return jsonb_build_object('error', 'BAD_MAP'); end if; insert into pin_failures(event_id, team_number) values (v_ev, -p_map); return jsonb_build_object('error', 'BAD_PIN'); end if; return join_team(p_event_code, v_num, p_pin, p_name, p_consent, p_rules, p_existing_token); end $$; create or replace function _weapon(p_team uuid) returns jsonb language sql stable as $$ select case when exists (select 1 from inventory where team_id = p_team and item_id = 'sniper' and qty > 0) then '{"id":"sniper","name":"Sniper","dmg":16,"range":0.11,"rate":1700,"mag":5,"reload":2600}'::jsonb when exists (select 1 from inventory where team_id = p_team and item_id = 'smg' and qty > 0) then '{"id":"smg","name":"SMG","dmg":2,"range":0.04,"rate":260,"mag":30,"reload":2000}'::jsonb else '{"id":"pistol","name":"Pistol","dmg":3,"range":0.055,"rate":650,"mag":12,"reload":1600}'::jsonb end $$; drop function if exists _blocked(float8, float8, float8, float8); create or replace function _blocked(p_ax float8, p_ay float8, p_bx float8, p_by float8) returns boolean language plpgsql stable as $$ declare b buildings; k int; f float8; px float8; py float8; begin for b in select * from buildings bb where greatest(p_ax, p_bx) >= bb.x0 and least(p_ax, p_bx) <= bb.x1 and greatest(p_ay, p_by) >= bb.y0 and least(p_ay, p_by) <= bb.y1 loop continue when (p_ax between b.x0 - 0.002 and b.x1 + 0.002 and p_ay between b.y0 - 0.002 and b.y1 + 0.002) or (p_bx between b.x0 - 0.002 and b.x1 + 0.002 and p_by between b.y0 - 0.002 and b.y1 + 0.002); for k in 1..15 loop f := k / 16.0; px := p_ax + (p_bx - p_ax) * f; py := p_ay + (p_by - p_ay) * f; if px between b.x0 and b.x1 and py between b.y0 and b.y1 then return true; end if; end loop; end loop; return false; end $$; create or replace function squad_fire(p_token text, p_target uuid) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; d teams; a arenas; w jsonb; me float8[]; you float8[]; dist float8; v_hit boolean; v_crit boolean := false; v_dmg int := 0; v_dealt int; v_knock boolean := false; v_mag int; v_rel timestamptz; v_chance float8; v_loot int; begin p := _auth_player(p_token); if p.role is null then raise exception 'NO_ROLE'; end if; select * into t from teams where id = p.team_id; select * into a from arenas where id = t.arena_id; if a.phase <> 'play' or a.paused then raise exception 'NO_FIGHTS_NOW'; end if; if coalesce(a.match_phase, 0) < _cfg(t.event_id, 'fire_from_phase') then raise exception 'NO_FIGHTS_YET'; end if; if not t.dropped or t.state in ('recovery', 'traveling') then raise exception 'BUSY'; end if; select * into d from teams where id = p_target; if d.id is null or d.arena_id <> t.arena_id or d.id = t.id or not d.ready then raise exception 'BAD_TARGET'; end if; if not d.dropped or d.state in ('recovery', 'traveling') then raise exception 'TARGET_DOWN'; end if; if d.protected_until is not null and d.protected_until > now() then raise exception 'TARGET_PROTECTED'; end if; if exists (select 1 from alliances al where al.status = 'active' and ((al.team_a = t.id and al.team_b = d.id) or (al.team_b = t.id and al.team_a = d.id))) then raise exception 'ALLY'; end if; if d.level <> t.level or (t.level > 0 and d.bldg is distinct from t.bldg) then raise exception 'NO_LINE_OF_SIGHT'; end if; w := _weapon(t.id); me := _team_xy(t); you := _team_xy(d); dist := sqrt((me[1] - you[1]) ^ 2 + (me[2] - you[2]) ^ 2); if dist > (w ->> 'range')::float8 then raise exception 'OUT_OF_RANGE'; end if; if t.level = 0 and _blocked(me[1], me[2], you[1], you[2]) then raise exception 'NO_LINE_OF_SIGHT'; end if; if p.reload_until is not null and p.reload_until > now() then raise exception 'RELOADING'; end if; if p.shot_at is not null and p.shot_at > now() - make_interval(secs => (w ->> 'rate')::float8 * 0.8 / 1000) then raise exception 'TOO_FAST'; end if; v_mag := coalesce(p.mag, (w ->> 'mag')::int); if v_mag > (w ->> 'mag')::int then v_mag := (w ->> 'mag')::int; end if; v_mag := v_mag - 1; if v_mag <= 0 then v_rel := now() + make_interval(secs => (w ->> 'reload')::float8 / 1000); v_mag := (w ->> 'mag')::int; end if; update players set shot_at = now(), mag = v_mag, reload_until = v_rel, last_seen_at = now() where id = p.id; update teams set protected_until = null, fight_at = now() where id = t.id and (protected_until is not null or fight_at is null or fight_at < now() - interval '3 seconds'); v_chance := 0.88 - 0.4 * dist / (w ->> 'range')::float8 - case when d.pos_at > now() - interval '1.5 seconds' and (abs(coalesce(d.vel_x, 0)) + abs(coalesce(d.vel_y, 0))) > 0.001 then 0.15 else 0 end - case when d.vehicle = 'in' then 0.05 else 0 end; v_hit := random() < v_chance; if v_hit then v_crit := random() < case when w ->> 'id' = 'sniper' then 0.3 else 0.12 end; v_dmg := (w ->> 'dmg')::int * case when v_crit then 2 else 1 end; v_dealt := _damage(d.id, v_dmg, 'gunfire', 'gf-' || gen_random_uuid()::text, 'Shot by Squad ' || t.number); select * into d from teams where id = d.id; v_knock := d.state = 'recovery'; update teams set fight_at = now() where id = d.id; if v_knock then v_loot := least(40, greatest(0, d.coins / 3)); if v_loot > 0 then perform _apply(d.id, 'looted', 0, -v_loot, 0, 0, 'loot-' || d.id || '-' || extract(epoch from d.recovery_deadline)::bigint, 'Looted by Squad ' || t.number); end if; perform _apply(t.id, 'knockout', _cfg(t.event_id, 'kill_points'), _cfg(t.event_id, 'kill_coins') + v_loot, 0, 0, 'ko-' || d.id || '-' || extract(epoch from d.recovery_deadline)::bigint, 'Knocked out Squad ' || d.number); update teams set kills = kills + 1 where id = t.id; perform _feed(a.id, 'squad.knocked', jsonb_build_object('team', d.number, 'by', t.number, 'weapon', w ->> 'id', 'shooter', p.display_name)); perform _ping_arena(a.id, 'knock'); end if; perform _ping_team(d.id, 'hit'); end if; if not exists (select 1 from game_feed f where f.arena_id = a.id and f.type = 'squad.gunfight' and f.at > now() - interval '30 seconds' and ((f.payload ->> 'a')::int in (t.number, d.number)) and ((f.payload ->> 'b')::int in (t.number, d.number))) then perform _feed(a.id, 'squad.gunfight', jsonb_build_object('a', t.number, 'b', d.number, 'location', coalesce(t.location_id, d.location_id))); end if; return jsonb_build_object('hit', v_hit, 'crit', v_crit, 'dmg', v_dmg, 'knocked', v_knock, 'target_hp', d.hp, 'target_shield', d.shield, 'weapon', w, 'mag', v_mag, 'reload_until', v_rel, 'from', to_jsonb(me), 'to', to_jsonb(you)); end $$; create or replace function _team_extra(t teams) returns jsonb language sql stable as $$ select jsonb_build_object('vehicle', t.vehicle, 'kills', t.kills, 'buggy', case when t.buggy_x is not null and t.vehicle <> 'in' then jsonb_build_array(t.buggy_x, t.buggy_y) when t.dropped and t.vehicle = 'none' and t.state <> 'traveling' then to_jsonb(_buggy_bay(t.number, (_team_xy(t))[1], (_team_xy(t))[2])) end, 'in_plane', not t.dropped and t.state <> 'traveling', 'parachute', not t.dropped and t.state = 'traveling', 'weapon', _weapon(t.id), 'fight_at', t.fight_at, 'land_at', case when not t.dropped and t.state = 'traveling' then t.travel_arrive_at end) $$; drop function if exists _player_state_v5(text); alter function player_state(text) rename to _player_state_v5; create function player_state(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare v jsonb; p players; t teams; a arenas; w jsonb; begin v := _player_state_v5(p_token); p := _auth_player(p_token); select * into t from teams where id = p.team_id; select * into a from arenas where id = t.arena_id; w := _weapon(t.id); v := jsonb_set(v, '{team}', (v -> 'team') || _team_extra(t)); v := jsonb_set(v, '{me}', (v -> 'me') || jsonb_build_object('mag', coalesce(least(p.mag, (w ->> 'mag')::int), (w ->> 'mag')::int), 'reload_until', case when p.reload_until > now() then p.reload_until end, 'seat', lpad(t.number::text, 2, '0') || chr(65 + greatest(0, (select count(*)::int from players q where q.team_id = t.id and q.joined_at < p.joined_at)) % 6))); return v; end $$; drop function if exists _spectator_state_v5(text); alter function spectator_state(text) rename to _spectator_state_v5; create function spectator_state(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare v jsonb; v_arena uuid; begin v := _spectator_state_v5(p_token); select id into v_arena from arenas where spectator_token = p_token; if v_arena is null or v -> 'squads' is null then return v; end if; return jsonb_set(v, '{squads}', (select coalesce(jsonb_agg(s || coalesce((select _team_extra(t) from teams t where t.arena_id = v_arena and t.number = (s ->> 'number')::int), '{}'::jsonb)), '[]'::jsonb) from jsonb_array_elements(v -> 'squads') s)); end $$; create or replace function arena_positions(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; v_scan boolean; begin p := _auth_player(p_token); select * into t from teams where id = p.team_id; if exists (select 1 from bots where arena_id = t.arena_id) then perform _tick(t.arena_id); end if; v_scan := t.scan_until is not null and t.scan_until > now(); return jsonb_build_object('server_now', now(), 'squads', (select coalesce(jsonb_agg(jsonb_build_object( 'id', tm.id, 'n', tm.number, 'level', tm.level, 'bldg', tm.bldg, 'state', tm.state, 'pos', to_jsonb(_team_xy(tm)), 'age', case when tm.state = 'idle' and tm.pos_at is not null then round(extract(epoch from now() - tm.pos_at)::numeric, 2) end, 'vel', case when tm.state = 'traveling' and tm.travel_arrive_at > now() and l.id is not null then jsonb_build_array((l.x - coalesce(tm.travel_fx, l.x)) / greatest(0.2, extract(epoch from tm.travel_arrive_at - tm.travel_started_at)), (l.y - coalesce(tm.travel_fy, l.y)) / greatest(0.2, extract(epoch from tm.travel_arrive_at - tm.travel_started_at))) when tm.state = 'idle' and tm.pos_at > now() - interval '3 seconds' and (tm.vel_x <> 0 or tm.vel_y <> 0) then jsonb_build_array(tm.vel_x, tm.vel_y) end, 'hp', tm.hp, 'shield', tm.shield, 'veh', tm.vehicle, 'buggy', case when tm.buggy_x is not null and tm.vehicle = 'parked' then jsonb_build_array(tm.buggy_x, tm.buggy_y) end, 'plane', not tm.dropped and tm.state <> 'traveling', 'chute', not tm.dropped and tm.state = 'traveling', 'land_at', case when not tm.dropped and tm.state = 'traveling' then tm.travel_arrive_at end, 'fight', tm.fight_at > now() - interval '4 seconds')), '[]'::jsonb) from teams tm left join locations l on l.id = tm.travel_to where tm.arena_id = t.arena_id and tm.ready and (tm.id = t.id or v_scan or tm.location_id = t.location_id or tm.jammed_until is null or tm.jammed_until < now() or tm.fight_at > now() - interval '4 seconds' or exists (select 1 from alliances al where al.status = 'active' and ((al.team_a = t.id and al.team_b = tm.id) or (al.team_b = t.id and al.team_a = tm.id)))))); end $$;
